def has_cycle(graph: dict) -> bool:
    UNVISITED, IN_PROGRESS, DONE = 0, 1, 2
    state = {}

    def visit(node):
        status = state.get(node, UNVISITED)
        if status == IN_PROGRESS:
            return True
        if status == DONE:
            return False
        state[node] = IN_PROGRESS
        for neighbor in graph.get(node, []):
            if visit(neighbor):
                return True
        state[node] = DONE
        return False

    for node in graph:
        if visit(node):
            return True
    return False
