def max_nonoverlapping(intervals: list) -> int:
    if not intervals:
        return 0
    intervals.sort(key=lambda x: x[1])
    count = 1
    last_end = intervals[0][1]
    for s, e in intervals[1:]:
        if s >= last_end:
            count += 1
            last_end = e
    return count
